 39	/** Emits: event(RunEvent), approval(ApprovalRequest), gateApproval(GateApproval) */
 40	export class PlanSession extends EventEmitter {
 41	  private q: Query | null = null;
 42	  private inbox: SDKUserMessage[] = [];
 43	  private wake: (() => void) | null = null;
 44	  private closed = false;
 45	  private toolStart = new Map<string, { name: string; t: number; out: string }>();
 46	  private lines = new Map<string, LineBuffer>(); // per parent id
 47	  private paused = false;
 48	  private pausedWaiters: Array<() => void> = [];
 49	  gateState = new Map<string, Verdict>();
 50	  planVerdict: "pass" | "fail" | null = null;
 51	  sessionId: string | null = null;
