 53	  constructor(readonly opts: SessionOpts) {
 54	    super();
 55	    for (const g of opts.plan?.gates ?? []) this.gateState.set(g.id, "pending");
 56	  }
 57	
 58	  private emitEv(ev: RunEvent) { this.emit("event", ev); }
 59	  private log(level: "debug" | "info" | "warn" | "error", source: string, message: string) { this.emitEv({ t: now(), kind: "log", level, source, message }); }
