161	  /** Each distinct verdict line is acted on once per turn-window; a later identical line (after a re-capture) counts again after 30s. */
162	  private async onVerdictLineOnce(line: string) {
163	    const key = line.replace(/[`*_\s]+/g, " ").trim();
164	    if (!parseVerdictLines(key).length) return;
165	    const last = this.seenAt.get(key);
166	    if (last !== undefined && now() - last < 30000) return;
167	    this.seenAt.set(key, now());
168	    await this.onVerdictLine(line);
169	  }
170	  private seenAt = new Map<string, number>();
171	
172	  private lineBuf(parent: string | null) { const k = parent ?? "main"; let b = this.lines.get(k); if (!b) { b = new LineBuffer(); this.lines.set(k, b); } return b; }
173	
174	  // ---- main loop ----
175	  async run(): Promise<{ verdict: "pass" | "fail" | "halted"; reason?: string }> {
176	    const o = this.opts;
177	    const options: Options = {
178	      cwd: o.cwd,
179	      env: o.env,
180	      model: o.model,
181	      maxTurns: o.maxTurns,
182	      includePartialMessages: true,
183	      permissionMode: o.approvals === "all" ? "default" : "bypassPermissions",
184	      allowDangerouslySkipPermissions: o.approvals !== "all",
185	      additionalDirectories: o.addDirs,
186	      settingSources: o.settingSources ?? [],
187	      hooks: { PreToolUse: [{ hooks: [this.preToolUse] }], PostToolUse: [{ hooks: [this.postToolUse] }] },
188	      canUseTool: this.canUseTool,
189	      ...(o.maxBudgetUsd ? { maxBudgetUsd: o.maxBudgetUsd } : {}),
190	      ...(o.resumeSessionId ? { resume: o.resumeSessionId } : {}),
191	      ...(o.pathToClaudeCodeExecutable ? { pathToClaudeCodeExecutable: o.pathToClaudeCodeExecutable } : {}),
192	    } as Options;
193	
194	    const t0 = now();
195	    this.q = query({ prompt: this.input(), options });
196	    let lastResultCost = 0;
197	    try {
198	      for await (const msg of this.q as AsyncIterable<SDKMessage>) {
199	        await this.handle(msg as SDKMessage & Record<string, unknown>);
200	        if ((msg as { type: string }).type === "result") {
201	          lastResultCost = (msg as { total_cost_usd?: number }).total_cost_usd ?? lastResultCost;
202	          // A turn ended. If the agent has declared the plan verdict, we're done.
203	          if (this.planVerdict || this.opts.plan === undefined) { this.close(); break; }
204	          // Otherwise nudge once: the contract requires a PLAN line.
205	          if (!this.nudged) { this.nudged = true; this.inject(`Vigil: the turn ended without a \`PLAN ${o.planId}: PASS|FAIL\` line. Continue the plan from where you stopped, or print the verdict line if it is complete.`); }
206	          else { this.close(); break; }
207	        }
208	      }
209	    } catch (err) {
210	      this.log("error", "sdk", String((err as Error)?.stack ?? err));
211	      this.close();
212	      return { verdict: "halted", reason: String((err as Error)?.message ?? err) };
213	    }
214	    const failed = [...this.gateState.entries()].filter(([, v]) => v === "fail").map(([k]) => k);
215	    if (!this.opts.plan) return this.lastResultOk ? { verdict: "pass" } : { verdict: "fail", reason: this.lastResultSubtype ? `result/${this.lastResultSubtype}` : "no result" };
216	    if (this.planVerdict === "pass" && failed.length === 0) return { verdict: "pass" };
217	    return { verdict: "fail", reason: failed.length ? `gates failed: ${failed.join(", ")}` : this.planVerdict === "fail" ? "agent reported PLAN FAIL" : `no plan verdict after ${Math.round((now() - t0) / 1000)}s` };
218	  }
219	  private nudged = false;
220	  private lastResultOk = false;
221	  private lastResultSubtype: string | null = null;
222	
223	  private async handle(msg: SDKMessage & Record<string, unknown>) {
224	    const p = this.opts.planId;
225	    switch (msg.type) {
226	      case "system": {
227	        if (msg.subtype === "init") {
228	          const m = msg as unknown as { session_id: string; model: string; tools: string[]; cwd: string };
229	          this.sessionId = m.session_id;
230	          this.emitEv({ t: now(), kind: "session.init", planId: p, sessionId: m.session_id, model: m.model, tools: m.tools ?? [], cwd: m.cwd });
231	        } else if (msg.subtype === "status" || msg.subtype === "notification" || msg.subtype === "api_retry" || msg.subtype === "compact_boundary") {
232	          this.log("info", "sdk", `${msg.subtype}${(msg as { text?: string }).text ? ": " + (msg as { text?: string }).text : ""}`);
233	        }
234	        break;
235	      }
236	      case "stream_event": {
237	        const ev = (msg as { event: { type: string; delta?: { type: string; text?: string } } }).event;
238	        const parent = (msg as { parent_tool_use_id: string | null }).parent_tool_use_id;
239	        if (ev.type === "content_block_delta" && ev.delta?.type === "text_delta" && ev.delta.text) {
240	          this.emitEv({ t: now(), kind: "assistant.delta", planId: p, text: ev.delta.text, parentToolUseId: parent });
241	          for (const line of this.lineBuf(parent).push(ev.delta.text)) await this.onVerdictLineOnce(line);
242	        }
243	        break;
244	      }
245	      case "assistant": {
246	        const m = msg as unknown as { message: { content: Array<{ type: string; text?: string; id?: string; name?: string; input?: unknown }> }; parent_tool_use_id: string | null };
247	        for (const block of m.message.content ?? []) {
248	          if (block.type === "text" && block.text) {
249	            this.emitEv({ t: now(), kind: "assistant.text", planId: p, text: block.text, parentToolUseId: m.parent_tool_use_id, final: true });
250	            for (const line of this.lineBuf(m.parent_tool_use_id).flush()) await this.onVerdictLineOnce(line);
251	            // Final text may contain verdict lines the delta path missed (no partials for some providers)
252	            for (const line of block.text.split(/\r?\n/)) await this.onVerdictLineOnce(line);
253	          } else if (block.type === "tool_use" && block.id && block.name) {
254	            this.toolStart.set(block.id, { name: block.name, t: now(), out: "" });
255	            this.emitEv({ t: now(), kind: "tool.start", planId: p, toolUseId: block.id, name: block.name, input: block.input, parentToolUseId: m.parent_tool_use_id });
256	          }
257	        }
258	        break;
259	      }
260	      case "tool_progress": {
261	        const m = msg as unknown as { tool_use_id: string; elapsed_time_seconds: number; heartbeat?: boolean };
262	        if (!m.heartbeat) this.log("debug", "tool", `${m.tool_use_id.slice(-6)} running ${m.elapsed_time_seconds}s`);
263	        break;
264	      }
265	      case "user": {
266	        const m = msg as unknown as { message: { content: string | Array<{ type: string; tool_use_id?: string; content?: unknown; is_error?: boolean }> } };
267	        if (Array.isArray(m.message.content)) {
268	          for (const block of m.message.content) {
269	            if (block.type === "tool_result" && block.tool_use_id) {
270	              const st = this.toolStart.get(block.tool_use_id);
271	              const text = typeof block.content === "string" ? block.content : Array.isArray(block.content) ? block.content.map((c) => (c as { text?: string }).text ?? "").join("\n") : JSON.stringify(block.content ?? "");
272	              this.emitEv({ t: now(), kind: "tool.output", planId: p, toolUseId: block.tool_use_id, chunk: text });
273	              this.emitEv({ t: now(), kind: "tool.end", planId: p, toolUseId: block.tool_use_id, ok: !block.is_error, durationMs: st ? now() - st.t : 0, output: text });
274	              this.toolStart.delete(block.tool_use_id);
275	            }
276	          }
277	        }
278	        break;
279	      }
280	      case "result": {
281	        const m = msg as unknown as { subtype: string; total_cost_usd: number; duration_ms: number; num_turns: number; usage: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }>; errors?: string[]; result?: string };
282	        const usage: TokenUsage = { input: m.usage?.input_tokens ?? 0, output: m.usage?.output_tokens ?? 0, cacheRead: m.usage?.cache_read_input_tokens ?? 0, cacheCreate: m.usage?.cache_creation_input_tokens ?? 0 };
283	        this.lastResultOk = m.subtype === "success" && !(m as { is_error?: boolean }).is_error; this.lastResultSubtype = m.subtype;
284	        this.emitEv({ t: now(), kind: "session.result", planId: p, subtype: m.subtype, costUsd: m.total_cost_usd ?? 0, durationMs: m.duration_ms ?? 0, turns: m.num_turns ?? 0, usage, modelUsage: m.modelUsage ?? {} });
285	        if (m.errors?.length) this.log("error", "sdk", m.errors.join("; "));
286	        if (m.result) for (const line of m.result.split(/\r?\n/)) await this.onVerdictLineOnce(line);
287	        break;
288	      }
289	      case "rate_limit_event": {
290	        const info = (msg as { rate_limit_info?: { status?: string; rateLimitType?: string; unifiedWindows?: Record<string, { utilization?: number }> } }).rate_limit_info;
291	        const util = info?.unifiedWindows ? Object.entries(info.unifiedWindows).map(([k, v]) => `${k} ${Math.round((v.utilization ?? 0) * 100)}%`).join(" · ") : "";
292	        this.log(info?.status && info.status !== "allowed" ? "warn" : "debug", "sdk", `rate limit ${info?.status ?? "?"} ${util}`);
293	        break;
294	      }
295	      default:
296	        this.log("debug", "sdk", `${msg.type}${"subtype" in msg ? "/" + String(msg.subtype) : ""}`);
297	    }
298	  }
299	}
