/** Replays a recorded events.jsonl through the same cockpit UI, time-scaled. */
import React from "react";
import { render } from "ink";
import { EventEmitter } from "node:events";
import type { RunEvent } from "./engine/events.js";
import { App } from "./ui/App.js";
import type { Runner } from "./engine/runner.js";

class ReplayRunner extends EventEmitter {
  approvals: "auto" | "gates" | "all" = "auto";
  session = null;
  models = new Map();
  store = { runId: "replay", dir: "" };
  requestStop() {}
  decide() {}
}

export async function renderReplay(evs: RunEvent[], speed: number): Promise<void> {
  const r = new ReplayRunner();
  const ink = render(React.createElement(App, { runner: r as unknown as Runner, animate: true, initialLevel: "info", planModels: new Map() }), { exitOnCtrlC: true });
  const t0 = evs[0].t;
  const start = Date.now();
  for (const ev of evs) {
    const due = start + (ev.t - t0) / Math.max(1, speed);
    const wait = due - Date.now();
    if (wait > 0) await new Promise((res) => setTimeout(res, Math.min(wait, 2000)));
    // re-stamp so fades/durations animate relative to now
    r.emit("event", { ...ev, t: Date.now() });
  }
  await ink.waitUntilExit();
}

import React from "react";
import { Box, Text } from "ink";
import type { UIState, ToolCard, GateView, PlanView, DiagRow } from "../state/reducer.js";
import { spinner, sparkline, progressBar, fmtDuration, fmtElapsed, fmtTokens, fadeLevel, truncate, clockHHMMSS, PULSE } from "./anim.js";

export const C = { accent: "#7aa2f7", ok: "#9ece6a", bad: "#f7768e", warn: "#e0af68", dim: "#565f89", text: "#c0caf5", muted: "#9aa5ce", tool: "#bb9af7", frame: "#3b4261" } as const;

function verdictIcon(v: string, tick: number, animate: boolean): { icon: string; color: string } {
  switch (v) {
    case "pass": return { icon: animate ? PULSE[tick % PULSE.length] : "✓", color: C.ok };
    case "fail": case "halted": return { icon: "✗", color: C.bad };
    case "running": return { icon: animate ? spinner(tick) : "▶", color: C.accent };
    case "skipped": return { icon: "↷", color: C.warn };
    default: return { icon: "○", color: C.dim };
  }
}

export function Header({ s, tick, animate, width }: { s: UIState; tick: number; animate: boolean; width: number }) {
  const elapsed = (s.endedAt ?? Date.now()) - s.startedAt;
  const live = s.endedAt ? (s.ok ? "done" : "halted") : "live";
  const liveColor = s.endedAt ? (s.ok ? C.ok : C.bad) : C.ok;
  const plansDone = s.plans.filter((p) => p.verdict === "pass").length;
  const gatesAll = s.plans.flatMap((p) => p.gates);
  const gatesDone = gatesAll.filter((g) => g.verdict === "pass").length;
  const frac = gatesAll.length ? gatesDone / gatesAll.length : 0;
  const cacheTotal = s.usage.input + s.usage.cacheRead + s.usage.cacheCreate;
  const cachePct = cacheTotal ? Math.round((s.usage.cacheRead / cacheTotal) * 100) : 0;
  const barW = Math.max(10, Math.min(40, width - 100));
  return (
    <Box flexDirection="column" borderStyle="round" borderColor={C.frame} paddingX={1}>
      <Box>
        <Text bold color={C.accent}>VIGIL</Text>
        <Text color={C.muted}>  {s.label}</Text>
        {s.activePlan && <Text color={C.text}>  ▶ {s.activePlan}</Text>}
        <Text>  </Text>
        <Text color={liveColor}>{animate && !s.endedAt ? (tick % 2 ? "●" : "○") : "●"} {live} {fmtDuration(elapsed)}</Text>
        <Text color={C.dim}>  {s.model}{s.baseUrl ? ` via ${s.baseUrl.replace(/^https?:\/\//, "")}` : ""}</Text>
        {s.paused && <Text color={C.warn}>  ⏸ PAUSED</Text>}
      </Box>
      <Box>
        <Text color={C.accent}>{progressBar(frac, barW)}</Text>
        <Text color={C.muted}>  plan {plansDone}/{s.plans.length} · gates {gatesDone}/{gatesAll.length} · turn {s.turns} · </Text>
        <Text color={C.ok}>${s.costUsd.toFixed(2)}</Text>
        <Text color={C.muted}> · {fmtTokens(s.usage.input + s.usage.cacheRead)} in / {fmtTokens(s.usage.output)} out · cache {cachePct}%</Text>
        <Text color={C.dim}> · rails ✓{s.hookCounts.allow} ⚠{s.hookCounts.warn} ✗{s.hookCounts.deny}</Text>
      </Box>
    </Box>
  );
}

function GateRow({ g, tick, animate, width }: { g: GateView; tick: number; animate: boolean; width: number }) {
  const { icon, color } = verdictIcon(g.verdict === "pending" ? "pending" : g.verdict === "running" ? "running" : g.verdict, tick, animate);
  const dur = g.startedAt ? fmtDuration((g.endedAt ?? Date.now()) - g.startedAt) : "";
  const present = g.evidence.filter((e) => e.present).length;
  return (
    <Box flexDirection="column">
      <Box>
        <Text color={color}>  {icon} </Text>
        <Text color={g.verdict === "pending" ? C.dim : C.text}>{truncate(g.id, width - 18).padEnd(Math.max(0, width - 18))}</Text>
        <Text color={C.dim}>{dur.padStart(6)}</Text>

  const origErr = process.stderr.write.bind(process.stderr);
  process.stderr.write = ((chunk: string | Uint8Array) => { const text = String(chunk).trim(); if (text) runner.emit("event", { t: Date.now(), kind: "log", level: /warn/i.test(text) ? "warn" : "error", source: "stderr", message: text.split("\n")[0].slice(0, 300) }); return true; }) as typeof process.stderr.write;
  const ink = render(React.createElement(App, { runner, animate, initialLevel: config.logLevel, planModels }), { exitOnCtrlC: true });
  process.on("exit", () => { process.stderr.write = origErr; });
  const ok = await startPromise;
  await ink.waitUntilExit();
  process.exit(ok ? 0 : 1);
}

function plainLine(ev: RunEvent): string | null {
  const ts = clockHHMMSS(ev.t);
  switch (ev.kind) {
    case "run.start": return `${ts} run ${ev.runId} (${ev.mode}) model=${ev.model}${ev.baseUrl ? ` via ${ev.baseUrl}` : ""}`;
    case "plan.start": return `${ts} ▶ plan ${ev.planId} gates=[${ev.gateIds.join(",")}]`;
    case "plan.end": return `${ts} ${ev.verdict === "pass" ? "✓" : "✗"} plan ${ev.planId} ${ev.verdict}${ev.reason ? " — " + ev.reason : ""} (${Math.round(ev.durationMs / 1000)}s)`;
    case "session.init": return `${ts} session ${ev.sessionId} model=${ev.model}`;
    case "session.result": return `${ts} result/${ev.subtype} turns=${ev.turns} cost=$${ev.costUsd.toFixed(3)}`;
    case "assistant.text": return ev.text.split("\n").filter((l) => l.trim()).map((l) => `${ts} ▍ ${l}`).join("\n");
    case "tool.start": return `${ts} ⚙ ${ev.name} ${JSON.stringify(ev.input).slice(0, 160)}`;
    case "tool.end": return `${ts}   └ ${ev.ok ? "ok" : "ERROR"} ${Math.round(ev.durationMs / 1000)}s ${ev.output.split("\n").slice(-1)[0]?.slice(0, 120) ?? ""}`;
    case "hook": return ev.decision === "observe" || ev.decision === "allow" ? null : `${ts} hook ${ev.event} ${ev.tool} ${ev.decision} — ${ev.reason}`;
    case "gate.update": return `${ts} gate ${ev.gateId} → ${ev.verdict.toUpperCase()}${ev.reason ? " — " + ev.reason : ""}${ev.evidence?.length ? ` evidence ${ev.evidence.filter((e) => e.present).length}/${ev.evidence.length}` : ""}`;
    case "probe": return ev.ok ? null : `${ts} probe ${ev.name} ✗ ${ev.detail}`;
    case "log": return ev.level === "debug" ? null : `${ts} ${ev.level} ${ev.source}: ${ev.message}`;
    case "control": return `${ts} ctl ${ev.action}${ev.detail ? ": " + ev.detail.slice(0, 100) : ""}`;
    case "run.end": return `${ts} run ${ev.ok ? "PASS" : "FAIL"}${ev.reason ? " — " + ev.reason : ""}`;
    default: return null;
  }
}

