/** Detects verdict lines the runner contract asks the agent to print. */
export type VerdictLine =
  | { type: "gate"; gateId: string; verdict: "pass" | "fail"; reason?: string }
  | { type: "task"; taskId: string }
  | { type: "plan"; planId: string; verdict: "pass" | "fail" };

const GATE_RE = /^\s*[`*_]*\s*(VG-[A-Z0-9-]+)\s*[`*_]*\s*:\s*[`*_]*\s*(PASS|FAIL)\b[`*_]*\s*(.*)$/i;
const TASK_RE = /^\s*[`*_]*\s*TASK\s+([\w-]+)\s*[`*_]*\s*:\s*DONE\b/i;
const PLAN_RE = /^\s*[`*_]*\s*PLAN\s+([\w-]+)\s*[`*_]*\s*:\s*[`*_]*\s*(PASS|FAIL)\b/i;

export function parseVerdictLines(text: string): VerdictLine[] {
  const out: VerdictLine[] = [];
  for (const line of text.split(/\r?\n/)) {
    let m = PLAN_RE.exec(line);
    if (m) { out.push({ type: "plan", planId: m[1], verdict: m[2].toLowerCase() as "pass" | "fail" }); continue; }
    m = GATE_RE.exec(line);
    if (m) { out.push({ type: "gate", gateId: m[1].toUpperCase(), verdict: m[2].toLowerCase() as "pass" | "fail", reason: m[3]?.trim().replace(/^[\s\-\u2013\u2014:]+/, "") || undefined }); continue; }
    m = TASK_RE.exec(line);
    if (m) out.push({ type: "task", taskId: m[1] });
