 22	function common(cmd: Command) {
 23	  return cmd
 24	    .option("-c, --config <file>", "vigil.config.json path")
 25	    .option("--cwd <dir>", "working directory for the agent")
 26	    .option("--model <id>", "model id (e.g. cc/claude-fable-5-1)")
