 36	async function launch(opts: Record<string, string | boolean | undefined>, mode: "plan" | "prompt", target?: string, prompt?: string, sel: { from?: string; to?: string; only?: string } = {}) {
 37	  const { config, source } = loadConfig(opts.config as string | undefined);
 38	  if (opts.model) config.model = String(opts.model);
 39	  if (opts.baseUrl) config.baseUrl = String(opts.baseUrl);
 40	  if (opts.log) config.logLevel = opts.log as "debug" | "info" | "warn";
 41	  if (opts.settings) config.settingSources = String(opts.settings).split(",").map((s) => s.trim()).filter(Boolean) as Array<"user" | "project" | "local">;
 42	  const approvals = ((opts.approvals as string) ?? config.approvals) as "auto" | "gates" | "all";
 43	  const cwd = resolve((opts.cwd as string) ?? config.cwd ?? process.cwd());
 44	  const animate = !opts.plain && config.animations && process.stdout.isTTY === true;
 45	  const runner = new Runner({ config, mode, target, prompt, cwd, approvals, from: sel.from, to: sel.to, only: sel.only, resume: opts.resume as string | undefined, pathToClaudeCodeExecutable: opts.claudeBin as string | undefined });
 46	
 47	  if (!animate && (opts.plain || !process.stdout.isTTY)) {
 48	    // plain mode: stream a readable log, still full observability on disk
 49	    let state: UIState = initialState();
 50	    runner.on("event", (ev: RunEvent) => {
 51	      state = reduce(state, ev);
 52	      const line = plainLine(ev);
 53	      if (line) process.stdout.write(line + "\n");
 54	    });
 55	    runner.on("approval", (req: { tool: string; resolve: (a: boolean) => void }) => { process.stdout.write(`[approval] ${req.tool} — auto-denied in --plain mode (use --approvals auto)\n`); req.resolve(false); });
 56	    runner.on("gateApproval", (g: { gateId: string; resolve: (a: boolean) => void }) => { process.stdout.write(`[gate] ${g.gateId} accepted (plain mode)\n`); g.resolve(true); });
 57	    // in plain mode a failure ends the run
 58	    runner.on("event", (ev: RunEvent) => { if (ev.kind === "plan.end" && ev.verdict !== "pass") setTimeout(() => runner.decide("quit"), 10); });
 59	    process.stdout.write(`vigil ${pkg.version} · config ${source} · ${mode} · approvals ${approvals} · cwd ${cwd}\n`);
 60	    const ok = await runner.start();
 61	    process.stdout.write(`\nRUN ${ok ? "PASS" : "FAIL"} · runs/${runner.store.runId}\n`);
 62	    process.exit(ok ? 0 : 1);
 63	  }
