/**
 * sdk-schema — the validated boundary between the Claude Agent SDK message
 * stream and Vigil's RunEvent vocabulary.
 *
 * Every schema is a zod v4 LOOSE object: the SDK declares large tails of fields
 * Vigil never reads, and future SDK versions will add more. Unknown extra fields
 * must pass through silently; only a missing/retyped field Vigil actually needs
 * is drift worth reporting.
 *
 * Two layers per message so a malformed message degrades instead of vanishing:
 *   - ENVELOPE — the fields Vigil must have to act at all (parse failure => skip).
 *   - DETAIL   — the fields Vigil reports but can survive without (parse failure
 *                => diagnose and continue with whatever is available).
 *
 * Field-by-field provenance (SDK 0.3.261 typings, and why each field is required
 * vs optional) is recorded in SDK_SHAPES.md. This module imports nothing from
 * session.ts — the dependency runs one way only.
 */
import { z } from "zod";

// ---- diagnostics vocabulary ----

/** One field-level reason a message failed its schema. `path` is dotted/bracketed, e.g. `message.content[0].type`. */
export interface SchemaIssue {
  path: string;
  code: string;
  message: string;
}

export type ParseResult<T> = { ok: true; value: T } | { ok: false; issues: SchemaIssue[] };

/** Render a zod issue path as a field path: `a.b[1].c`. An empty path (the whole value) renders as `(root)`. */
export function formatPath(path: PropertyKey[]): string {
  let out = "";
  for (const seg of path) {
    const s = String(seg);
    if (typeof seg === "number" || /^\d+$/.test(s)) out += `[${s}]`;
    else out += out === "" ? s : `.${s}`;
  }
  return out === "" ? "(root)" : out;
}

/** safeParse wrapper that never throws and always yields at least one issue on failure. */
export function parseWith<T>(schema: z.ZodType<T>, schemaName: string, input: unknown): ParseResult<T> {
  let res: z.ZodSafeParseResult<T>;
  try {
    res = schema.safeParse(input);
  } catch (err) {
    // A schema must never take a run down, however hostile the input.
    return { ok: false, issues: [{ path: "(root)", code: "parse_threw", message: `${schemaName} threw: ${String((err as Error)?.message ?? err)}` }] };
  }
  if (res.success) return { ok: true, value: res.data };
  const issues: SchemaIssue[] = res.error.issues.map((i) => ({ path: formatPath(i.path as PropertyKey[]), code: String(i.code ?? "invalid"), message: i.message }));
  return { ok: false, issues: issues.length ? issues : [{ path: "(root)", code: "invalid_type", message: `${schemaName} rejected the input` }] };
}

/** Re-root issue paths under a parent path, e.g. prefixIssues("message.content[2]", [{path:"type"}]) => `message.content[2].type`. */
export function prefixIssues(prefix: string, issues: SchemaIssue[]): SchemaIssue[] {
  return issues.map((i) => ({ ...i, path: i.path === "(root)" ? prefix : `${prefix}.${i.path}` }));
}

/** A truncated, always-safe rendering of an offending message for a diagnostic event. */
export function sampleOf(input: unknown, max = 300): string {
  let s: string;
  try {
    s = JSON.stringify(input, (_k, v: unknown) => (typeof v === "bigint" ? String(v) : v)) ?? String(input);
  } catch {
    try {
      s = String(input);
    } catch {
      s = "(unserialisable)";
    }
  }
  return s.length > max ? s.slice(0, max) + "…" : s;
}

// ---- the outermost gate ----

/** Every incoming message is parsed through this first; `type` drives the dispatch. */
export const SdkEnvelopeSchema = z.looseObject({ type: z.string() });
=== STORE ===
/**
 * RunStore — everything a run observes goes to disk:
 *   runs/<id>/events.jsonl   every RunEvent, one per line
 *   runs/<id>/tools/<n>-<tool>.txt   full input + output per tool call
 *   runs/<id>/gates.json     latest verdict + evidence per gate
 *   runs/<id>/cost.json      per-plan and per-model usage
 *   runs/<id>/session.json   SDK session ids per plan (for resume)
 */
import { mkdirSync, appendFileSync, writeFileSync, existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { RunEvent, Verdict } from "./events.js";

export interface GateRecord { planId: string; gateId: string; verdict: Verdict; reason?: string; evidence: { path: string; present: boolean; bytes: number }[]; updatedAt: number; }

export class RunStore {
  readonly dir: string;
  private toolSeq = 0;
  private toolFiles = new Map<string, string>();
  private streamed = new Set<string>();
  private gates: Record<string, GateRecord> = {};
  private sessions: Record<string, string> = {};
  private cost: Record<string, unknown> = {};

  constructor(readonly runsRoot: string, readonly runId: string) {
    this.dir = join(runsRoot, runId);
    mkdirSync(join(this.dir, "tools"), { recursive: true });
  }

  static newRunId(label: string): string {
    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
    return `${ts}-${label.replace(/[^\w.-]+/g, "_").slice(0, 40)}`;
  }

  append(ev: RunEvent): void {
    appendFileSync(join(this.dir, "events.jsonl"), JSON.stringify(ev) + "\n");
    switch (ev.kind) {
      case "tool.start": {
        const f = join(this.dir, "tools", `${String(++this.toolSeq).padStart(4, "0")}-${ev.name}.txt`);
        this.toolFiles.set(ev.toolUseId, f);
        writeFileSync(f, `# ${ev.name}  ${new Date(ev.t).toISOString()}  id=${ev.toolUseId}${ev.parentToolUseId ? `  parent=${ev.parentToolUseId}` : ""}\n## input\n${JSON.stringify(ev.input, null, 2)}\n## output\n`);
        break;
      }
      case "tool.output": { const f = this.toolFiles.get(ev.toolUseId); if (f) { appendFileSync(f, ev.chunk); this.streamed.add(ev.toolUseId); } break; }
      case "tool.end": { const f = this.toolFiles.get(ev.toolUseId); if (f) appendFileSync(f, `\n## end ok=${ev.ok} durationMs=${ev.durationMs}\n${this.streamed.has(ev.toolUseId) ? "" : ev.output.slice(-20000) + "\n"}`); this.streamed.delete(ev.toolUseId); break; }
      case "gate.update": {
        this.gates[`${ev.planId}/${ev.gateId}`] = { planId: ev.planId, gateId: ev.gateId, verdict: ev.verdict, reason: ev.reason, evidence: ev.evidence ?? [], updatedAt: ev.t };
        writeFileSync(join(this.dir, "gates.json"), JSON.stringify(this.gates, null, 2));
        break;
      }
      case "session.init": { this.sessions[ev.planId] = ev.sessionId; writeFileSync(join(this.dir, "session.json"), JSON.stringify(this.sessions, null, 2)); break; }
      case "session.result": { this.cost[ev.planId] = { costUsd: ev.costUsd, durationMs: ev.durationMs, turns: ev.turns, usage: ev.usage, modelUsage: ev.modelUsage }; writeFileSync(join(this.dir, "cost.json"), JSON.stringify(this.cost, null, 2)); break; }
    }
  }

  gatesForPlan(planId: string): GateRecord[] { return Object.values(this.gates).filter((g) => g.planId === planId); }

  static readEvents(dir: string): RunEvent[] {
    const f = join(dir, "events.jsonl");
    if (!existsSync(f)) return [];
    return readFileSync(f, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l) as RunEvent);
  }
}
